        out.append((sid, label))
    return out[:24]

JUMP = '\n'.join('<button class="jump" data-t="%s">%s</button>' % (sid, html.escape(lbl))
                 for sid, lbl in sections(PAGE))
if not JUMP:
    JUMP = '<span class="lbl">keine Abschnitte mit id gefunden</span>'

SRCDOC = html.escape(PAGE, quote=True)

